using System.ComponentModel;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ExternalApiTool
{
    [McpServerTool, Description("Fetches data from an external API for the given resource path.")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        ILogger<IMcpServer> logger,
        [Description("The resource path to fetch (e.g. \"users/1\")")] string path)
    {
        logger.LogInformation("Fetching external API resource: {Path}", path);

        var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsStringAsync();
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired summary style (e.g. brief, detailed, bullet-points)")] string style = "brief")
    {
        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content
                {
                    Text = $"Summarize the following text in a {style} style:\n\n{text}"
                }
            }
        ];
    }
}

